// Load saved custom team/player names from localStorage if available (ignoring generic Player #N placeholders)
try {
  const savedNames = typeof localStorage !== 'undefined' ? localStorage.getItem('ctf_custom_team_names') : null;
  if (savedNames) {
    const parsed = JSON.parse(savedNames) as Partial<Record<TeamId, string>>;
    (['red', 'blue', 'green', 'yellow'] as TeamId[]).forEach((id) => {
      const candidate = parsed[id]?.trim();
      if (candidate && !/^Player\s*#?\d+$/i.test(candidate)) {
        TEAMS_CONFIG[id].name = candidate;
      }
    });
  }
} catch (e) {}

function saveCustomTeamNames() {
  try {
    const data: Record<TeamId, string> = {
      red: TEAMS_CONFIG.red.name,
      blue: TEAMS_CONFIG.blue.name,
      green: TEAMS_CONFIG.green.name,
      yellow: TEAMS_CONFIG.yellow.name,
    };
    localStorage.setItem('ctf_custom_team_names', JSON.stringify(data));
  } catch (e) {}
}

