// ==========================================
// --- INITIALIZE DRIVING RANGE ENVIRONMENT ---
// ==========================================
async function setupWorld() {
  gameContext.timer.connect(document);

  const canvas = document.getElementById('canvas');
  if (!canvas || !(canvas instanceof HTMLCanvasElement)) {
    throw new Error('Canvas element missing or invalid');
  }

  // Determine initial graphics quality (URL param -> localStorage -> setupData -> default Epic)
  let initialQuality = QualityMode.Epic;
  try {
    const urlParams = new URLSearchParams(window.location.search);
    const qParam = urlParams.get('quality');
    const storedQ = typeof localStorage !== 'undefined' ? localStorage.getItem('ogs_graphics_quality') : null;
    initialQuality = parseQuality(qParam || storedQ || gameContext.setupData?.qualityLevel || 'epic');
  } catch (e) {
    initialQuality = QualityMode.Epic;
  }
  gameContext.currentQuality = initialQuality;

  gameContext.renderer = new FuseRenderer({
    canvas,
    adaptive: false,
    antialias: true,
    renderMode: 'webgpu',
    forceWebGL: gameContext.setupData?.backend === 'webgl',
    qualityLevel: initialQuality,
  });

  await gameContext.renderer.init();
  const crispDpr = Math.min(typeof window !== 'undefined' ? (window.devicePixelRatio || 1) : 1, 2.0);
  gameContext.renderer.renderer.setPixelRatio(crispDpr);
}

// Compute exact world Z coordinate of a flag from its radial distance and lateral offset
function getFlagWorldZ(config: FlagConfig): number {
  return Math.sqrt(
    Math.max(100, config.distanceMeters * config.distanceMeters - config.lateralOffsetMeters * config.lateralOffsetMeters)
  );
}

// Local 3D putting surface contour offset relative to pin elevation
function getGreenLocalContourOffset(r: number, greenR: number, contourType: GreenContourType): number {
  const normR = Math.min(1.35, r / greenR);
  if (contourType === 'bowl') {
    // Smooth concave collection bowl (+0.28m at edge funneling smoothly down to 0 at pin)
    return normR * normR * 0.28;
  } else if (contourType === 'plateau') {
    // Gentle crowned table-top (-0.16m runoff toward outer rim)
    return - normR * normR * 0.16;
  } else if (contourType === 'tier') {
    // Subtle championship tier dish (+0.14m rim)
    return normR * normR * 0.14;
  }
  // 'ridge': slight false-front crown (-0.08m)
  return - normR * normR * 0.08;
}

// Deterministic 3D golf course elevation model (Smooth Links Hills, Collection Bowls & Elevated Plateaus)
function getCourseElevation(x: number, z: number): number {
  // Keep tee box area (near origin) completely flat
  if (z < 14) {
    const t = Math.max(0, (z - 6) / 8);
    return t * t * (3 - 2 * t) * 0.08 * Math.sin(x * 0.12);
  }

  // Base rolling links fairway undulations + spectator mounding along sides (|x| > 30m)
  let h =
    Math.sin(x * 0.055 + z * 0.035) * 0.24 +
    Math.cos(x * 0.08 - z * 0.045) * 0.16;

  const sideDist = Math.max(0, Math.abs(x) - 30);
  if (sideDist > 0) {
    const mound = Math.min(2.4, sideDist * 0.09) * (0.65 + 0.35 * Math.sin(z * 0.07 + x * 0.09));
    h += mound;
  }

  // Blend in each Flag Complex's 3D green pad over a wide 14m cosine apron (zero sharp steps!)
  for (let i = 0; i < FLAGS_CONFIG.length; i++) {
    const cfg = FLAGS_CONFIG[i];
    const fx = cfg.lateralOffsetMeters;
    const fz = getFlagWorldZ(cfg);
    const dx = x - fx;
    const dz = z - fz;
    const r = Math.hypot(dx, dz);
    const greenR = getGreenRadius(cfg);
    const outerR = greenR + 14.0;

    if (r < outerR) {
      let w = 1.0;
      if (r > greenR) {
        const u = (r - greenR) / (outerR - greenR);
        w = 0.5 * (1 + Math.cos(Math.PI * u));
      }

      const contourOffset = getGreenLocalContourOffset(r, greenR, cfg.contourType);
      const targetH = cfg.elevationMeters + contourOffset;
      h = h * (1 - w) + targetH * w;
    }
  }

  return h;
}

// Compute the exact raised putting green complex surface Y at any world (x, z)
// Sitting +0.12m above the coarse fairway grid inside greenRadius and tapering smoothly to 0 over the 1.4m apron.
function getGreenComplexPadLift(r: number, greenR: number): number {
  const apronWidth = 1.4;
  if (r <= greenR) return 0.12;
  if (r >= greenR + apronWidth) return 0.0;
  const t = (r - greenR) / apronWidth;
  return 0.12 * 0.5 * (1 + Math.cos(Math.PI * t));
}

function getGreenSurfaceWorldY(x: number, z: number): number {
  let baseH = getCourseElevation(x, z);
  let maxLift = 0;
  for (let i = 0; i < FLAGS_CONFIG.length; i++) {
    const cfg = FLAGS_CONFIG[i];
    const fx = cfg.lateralOffsetMeters;
    const fz = getFlagWorldZ(cfg);
    const r = Math.hypot(x - fx, z - fz);
    const greenR = getGreenRadius(cfg);
    if (r < greenR + 1.4) {
      maxLift = Math.max(maxLift, getGreenComplexPadLift(r, greenR));
    }
  }
  return baseH + maxLift;
}


function mergeBufferGeometries(geometries: THREE.BufferGeometry[]): THREE.BufferGeometry {
  let totalVerts = 0;
  let totalIndices = 0;
  for (const g of geometries) {
    totalVerts += g.attributes.position.count;
    if (g.index) totalIndices += g.index.count;
    else totalIndices += g.attributes.position.count;
  }

  const positions = new Float32Array(totalVerts * 3);
  const normals = new Float32Array(totalVerts * 3);
  const colors = new Float32Array(totalVerts * 3);
  const indices = new Uint32Array(totalIndices);

  let vOffset = 0;
  let iOffset = 0;

  for (const g of geometries) {
    const pos = g.attributes.position;
    const norm = g.attributes.normal;
    const col = g.attributes.color;
    const count = pos.count;

    positions.set(pos.array as Float32Array, vOffset * 3);
    if (norm) normals.set(norm.array as Float32Array, vOffset * 3);
    if (col) {
      colors.set(col.array as Float32Array, vOffset * 3);
    } else {
      colors.fill(1, vOffset * 3, (vOffset + count) * 3);
    }

    if (g.index) {
      const idxArr = g.index.array;
      for (let j = 0; j < idxArr.length; j++) {
        indices[iOffset + j] = idxArr[j] + vOffset;
      }
      iOffset += idxArr.length;
    } else {
      for (let j = 0; j < count; j++) {
        indices[iOffset + j] = vOffset + j;
      }
      iOffset += count;
    }
    vOffset += count;
  }

  const merged = new THREE.BufferGeometry();
  merged.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  merged.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
  merged.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  merged.setIndex(new THREE.BufferAttribute(indices, 1));
  return merged;
}

function createOrganicBunkerTexture(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.clearRect(0, 0, 512, 512);

    // Draw a soft kidney-bean sand bunker shape using radial gradients
    const lobes = [
      { cx: 195, cy: 256, rx: 145, ry: 125 },
      { cx: 315, cy: 248, rx: 140, ry: 120 },
      { cx: 256, cy: 274, rx: 130, ry: 110 },
    ];

    // Outer grassy lip shadow
    lobes.forEach((l) => {
      const g = ctx.createRadialGradient(l.cx, l.cy, l.rx * 0.65, l.cx, l.cy, l.rx);
      g.addColorStop(0.0, 'rgba(138, 114, 72, 0.95)');
      g.addColorStop(0.78, 'rgba(92, 112, 64, 0.65)');
      g.addColorStop(1.0, 'rgba(45, 90, 39, 0.0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(l.cx, l.cy, l.rx, 0, Math.PI * 2);
      ctx.fill();
    });

    // Inner bright sculpted sand basin
    lobes.forEach((l) => {
      const g = ctx.createRadialGradient(l.cx - 10, l.cy - 8, 8, l.cx, l.cy, l.rx * 0.82);
      g.addColorStop(0.0, 'rgba(247, 232, 198, 1.0)');
      g.addColorStop(0.65, 'rgba(232, 210, 166, 0.98)');
      g.addColorStop(0.88, 'rgba(186, 156, 104, 0.85)');
      g.addColorStop(1.0, 'rgba(186, 156, 104, 0.0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(l.cx, l.cy, l.rx * 0.82, 0, Math.PI * 2);
      ctx.fill();
    });
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function createFairwayBunkers() {
  if (!gameContext.scene) return;
  const bunkerTex = createOrganicBunkerTexture();
  const bunkerMat = new THREE.MeshStandardMaterial({
    map: bunkerTex,
    transparent: true,
    alphaTest: 0.04,
    roughness: 0.88,
    metalness: 0.02,
    depthWrite: false,
    polygonOffset: true,
    polygonOffsetFactor: -1,
    polygonOffsetUnits: -1,
  });

  BUNKER_DEFS.forEach((b) => {
    const cfg = FLAGS_CONFIG[b.flagIdx];
    if (!cfg) return;
    const fz = getFlagWorldZ(cfg);
    const bx = cfg.lateralOffsetMeters + b.offsetX;
    const bz = fz + b.offsetZ;

    const geo = new THREE.PlaneGeometry(b.width, b.length, 24, 24);
    geo.rotateX(-Math.PI / 2);
    geo.rotateY(b.rotY);

    const pos = geo.attributes.position as THREE.BufferAttribute;
    for (let i = 0; i < pos.count; i++) {
      const lx = pos.getX(i);
      const lz = pos.getZ(i);
      const wx = bx + lx;
      const wz = bz + lz;
      const wy = getCourseElevation(wx, wz) + 0.028;
      pos.setXYZ(i, wx, wy, wz);
    }
    geo.computeVertexNormals();

    const mesh = new THREE.Mesh(geo, bunkerMat);
    mesh.receiveShadow = true;
    mesh.renderOrder = 1;
    gameContext.scene?.add(mesh);
  });
}

function createTreeFlanks() {
  if (!gameContext.scene) return;

  const trunkGeos: THREE.BufferGeometry[] = [];
  const canopyGeos: THREE.BufferGeometry[] = [];

  // Deterministic pseudo-random helper
  let seed = 1337;
  const rand = () => {
    seed = (seed * 16807) % 2147483647;
    return (seed - 1) / 2147483646;
  };

  const treePlacements: { x: number; z: number; h: number; r: number }[] = [];

  // 1. Dense Left & Right Flanking Corridors (|x| from 35m to 92m, z from -6m to 255m)
  for (let z = -6; z <= 252; z += 7.5) {
    // Inner hero trees along fairway edge (|x| ~ 35..44m) that cast long Golden Hour shadows across the fairway
    const leftInnerX = 35.5 + rand() * 7.5;
    const rightInnerX = -(35.5 + rand() * 7.5);
    treePlacements.push({
      x: leftInnerX,
      z: z + (rand() - 0.5) * 4.0,
      h: 13.5 + rand() * 6.5,
      r: 4.2 + rand() * 2.1,
    });
    treePlacements.push({
      x: rightInnerX,
      z: z + (rand() - 0.5) * 4.0,
      h: 13.0 + rand() * 6.5,
      r: 4.2 + rand() * 2.1,
    });

    // Mid-depth & outer forest rows (|x| ~ 45..88m)
    for (let row = 0; row < 2; row++) {
      const lx = 46 + row * 16 + rand() * 12;
      const rx = -(46 + row * 16 + rand() * 12);
      treePlacements.push({
        x: lx,
        z: z + (rand() - 0.5) * 6.0,
        h: 14.5 + rand() * 8.0,
        r: 4.8 + rand() * 2.4,
      });
      treePlacements.push({
        x: rx,
        z: z + (rand() - 0.5) * 6.0,
        h: 14.5 + rand() * 8.0,
        r: 4.8 + rand() * 2.4,
      });
    }
  }

  // 2. Distant Horizon Forest Backdrop behind Flag 10 (z = 244m to 278m, x = -85m to +85m)
  for (let x = -84; x <= 84; x += 7.5) {
    for (let row = 0; row < 2; row++) {
      treePlacements.push({
        x: x + (rand() - 0.5) * 4.5,
        z: 245 + row * 12 + rand() * 7.0,
        h: 14.0 + rand() * 7.5,
        r: 4.6 + rand() * 2.2,
      });
    }
  }

  const barkDark = new THREE.Color('#36251a');
  const barkLight = new THREE.Color('#543b28');
  const leafDeep = new THREE.Color('#1a3819');
  const leafMid = new THREE.Color('#2d5724');
  const leafSun = new THREE.Color('#748f2e');
  const leafGold = new THREE.Color('#a4b03f');
  const tmpCol = new THREE.Color();

  // Sun direction vector for backlit Golden Hour rim-tint
  const sunDir = new THREE.Vector3(185, 68, 95).normalize();

  treePlacements.forEach((t) => {
    const baseY = getCourseElevation(t.x, t.z) - 0.2;
    const trunkH = t.h * 0.38;
    const trunkRTop = t.r * 0.065;
    const trunkRBot = t.r * 0.115;

    const trunkGeo = new THREE.CylinderGeometry(trunkRTop, trunkRBot, trunkH, 7, 1);
    trunkGeo.translate(t.x, baseY + trunkH * 0.5, t.z);
    const tPos = trunkGeo.attributes.position as THREE.BufferAttribute;
    const tNorm = trunkGeo.attributes.normal as THREE.BufferAttribute;
    const tCols = new Float32Array(tPos.count * 3);
    for (let i = 0; i < tPos.count; i++) {
      const nx = tNorm.getX(i);
      const nz = tNorm.getZ(i);
      const sunDot = Math.max(0, nx * sunDir.x + nz * sunDir.z);
      tmpCol.copy(barkDark).lerp(barkLight, sunDot * 0.75);
      tCols[i * 3] = tmpCol.r;
      tCols[i * 3 + 1] = tmpCol.g;
      tCols[i * 3 + 2] = tmpCol.b;
    }
    trunkGeo.setAttribute('color', new THREE.BufferAttribute(tCols, 3));
    trunkGeos.push(trunkGeo);

    // 5 organic broadleaf foliage puffs per tree
    const puffs = [
      { ox: 0, oy: t.h * 0.56, oz: 0, rx: t.r * 0.95, ry: t.h * 0.28, rz: t.r * 0.95 },
      { ox: -t.r * 0.35, oy: t.h * 0.48, oz: t.r * 0.22, rx: t.r * 0.72, ry: t.h * 0.22, rz: t.r * 0.72 },
      { ox: t.r * 0.36, oy: t.h * 0.50, oz: -t.r * 0.20, rx: t.r * 0.74, ry: t.h * 0.23, rz: t.r * 0.74 },
      { ox: t.r * 0.15, oy: t.h * 0.72, oz: t.r * 0.28, rx: t.r * 0.76, ry: t.h * 0.24, rz: t.r * 0.76 },
      { ox: -t.r * 0.12, oy: t.h * 0.86, oz: -t.r * 0.08, rx: t.r * 0.62, ry: t.h * 0.20, rz: t.r * 0.62 },
    ];

    const treeHueShift = rand() * 0.35;
    puffs.forEach((p) => {
      const puffGeo = new THREE.IcosahedronGeometry(1.0, 1);
      puffGeo.scale(p.rx, p.ry, p.rz);
      puffGeo.translate(t.x + p.ox, baseY + p.oy, t.z + p.oz);
      puffGeo.computeVertexNormals();

      const cPos = puffGeo.attributes.position as THREE.BufferAttribute;
      const cNorm = puffGeo.attributes.normal as THREE.BufferAttribute;
      const cCols = new Float32Array(cPos.count * 3);

      for (let i = 0; i < cPos.count; i++) {
        const nx = cNorm.getX(i);
        const ny = cNorm.getY(i);
        const nz = cNorm.getZ(i);
        const dot = Math.max(0, nx * sunDir.x + ny * sunDir.y + nz * sunDir.z);
        tmpCol.copy(leafDeep).lerp(leafMid, 0.35 + ny * 0.35);
        if (dot > 0.15) {
          tmpCol.lerp(leafSun, Math.min(1, dot * 0.95));
        }
        if (dot > 0.55) {
          tmpCol.lerp(leafGold, (dot - 0.55) * (0.55 + treeHueShift));
        }
        cCols[i * 3] = tmpCol.r;
        cCols[i * 3 + 1] = tmpCol.g;
        cCols[i * 3 + 2] = tmpCol.b;
      }
      puffGeo.setAttribute('color', new THREE.BufferAttribute(cCols, 3));
      canopyGeos.push(puffGeo);
    });
  });

  const mergedTrunks = mergeBufferGeometries(trunkGeos);
  const trunkMat = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.92,
    metalness: 0.02,
  });
  const trunkMesh = new THREE.Mesh(mergedTrunks, trunkMat);
  trunkMesh.castShadow = true;
  trunkMesh.receiveShadow = true;
  gameContext.scene.add(trunkMesh);

  const mergedCanopies = mergeBufferGeometries(canopyGeos);
  const canopyMat = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.78,
    metalness: 0.02,
    flatShading: true,
  });
  const canopyMesh = new THREE.Mesh(mergedCanopies, canopyMat);
  canopyMesh.castShadow = true;
  canopyMesh.receiveShadow = true;
  gameContext.scene.add(canopyMesh);

  trunkGeos.forEach((g) => g.dispose());
  canopyGeos.forEach((g) => g.dispose());
}

