async function createDrivingRange() {
  if (!gameContext.scene) return;

  // High-fidelity procedural fairway turf with crisp mowing stripes & micro-blade normals
  const maxAniso = gameContext.renderer?.getMaxAnisotropy() || 16;
  const fairwayTextures = getProceduralFairwayTextures(maxAniso);
  fairwayTextures.map.repeat.set(48, 96);
  fairwayTextures.normalMap.repeat.set(48, 96);

  // Sculpted 3D Course Geometry (360m wide x 420m long, ultra-smooth 220x280 grid with zero step trenches)
  const floorGeometry = new THREE.PlaneGeometry(360, 420, 220, 280);
  floorGeometry.rotateX(-Math.PI / 2);

  const posAttr = floorGeometry.attributes.position as THREE.BufferAttribute;
  const colors = new Float32Array(posAttr.count * 3);
  const cFairway = new THREE.Color('#ffffff');
  const cRough = new THREE.Color('#74a17e');
  const cHigh = new THREE.Color('#e2f5d0');
  const cLow = new THREE.Color('#9bd1e5');
  const tmpColor = new THREE.Color();

  for (let i = 0; i < posAttr.count; i++) {
    const vx = posAttr.getX(i);
    const vz = posAttr.getZ(i) + 175; // Shift plane so Z spans [-35m, +385m]
    posAttr.setZ(i, vz);

    const vy = getCourseElevation(vx, vz);
    posAttr.setY(i, vy);

    // Subtle elevation & rough tinting so 3D mounds and bowls pop visually
    if (Math.abs(vx) > 30) {
      const tRough = Math.min(1, (Math.abs(vx) - 30) / 14);
      tmpColor.copy(cFairway).lerp(cRough, tRough * 0.50);
    } else if (vy > 0.6) {
      tmpColor.copy(cFairway).lerp(cHigh, Math.min(1, (vy - 0.6) / 2.5) * 0.28);
    } else if (vy < -0.5) {
      tmpColor.copy(cFairway).lerp(cLow, Math.min(1, (-0.5 - vy) / 1.8) * 0.20);
    } else {
      tmpColor.copy(cFairway);
    }
    colors[i * 3] = tmpColor.r;
    colors[i * 3 + 1] = tmpColor.g;
    colors[i * 3 + 2] = tmpColor.b;
  }

  floorGeometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  floorGeometry.computeVertexNormals();

  const floorMaterial = new THREE.MeshStandardMaterial({
    map: fairwayTextures.map,
    normalMap: fairwayTextures.normalMap,
    normalScale: new THREE.Vector2(0.65, 0.65),
    vertexColors: true,
    roughness: 0.68,
    metalness: 0.04,
  });

  gameContext.ground = new THREE.Mesh(floorGeometry, floorMaterial);
  gameContext.ground.receiveShadow = true;
  gameContext.ground.userData.surface = 'fairway';
  gameContext.scene.add(gameContext.ground);

  gameContext.volumetricBeams = [];

  // Create sculpted organic sand bunkers, dense Golden Hour tree corridors & low sunset orb
  createFairwayBunkers();
  createTreeFlanks();
  createGoldenHourSunOrb();

  // Sunlit normal-mapped background mountains (bagStand omitted for clean broadcast tee box)
  try {
    const textureLoader = new THREE.TextureLoader(gameContext.loadingScreen?.manager);
    const mtnGrassTexture = textureLoader.load(fairwayTexture);
    mtnGrassTexture.wrapS = THREE.RepeatWrapping;
    mtnGrassTexture.wrapT = THREE.RepeatWrapping;
    mtnGrassTexture.repeat.set(100, 140);
    mtnGrassTexture.colorSpace = THREE.SRGBColorSpace;
    mtnGrassTexture.anisotropy = maxAniso;

    const mtnNormalMap = textureLoader.load(fairwayMap);
    mtnNormalMap.wrapS = THREE.RepeatWrapping;
    mtnNormalMap.wrapT = THREE.RepeatWrapping;
    mtnNormalMap.repeat.set(100, 140);
    mtnNormalMap.colorSpace = THREE.SRGBColorSpace;
    mtnNormalMap.anisotropy = maxAniso;

    const mountainMaterial = new THREE.MeshStandardMaterial({
      map: mtnGrassTexture,
      normalMap: mtnNormalMap,
      roughness: 1,
      color: mountainColor,
      displacementScale: 0.5,
      normalScale: new THREE.Vector2(0, 0.5),
      metalness: 0,
    });

    const mountain = await gameContext.meshLoader?.load(rangeMtnsModel, true);
    if (mountain) {
      // @ts-expect-error
      mountain.material = mountainMaterial;
      mountain.traverse((child) => {
        if ((child as THREE.Mesh).isMesh) {
          (child as THREE.Mesh).material = mountainMaterial;
        }
      });
      mountain.position.set(0, -12, 900);
      mountain.scale.set(20, 20, 20);
      gameContext.scene.add(mountain);
    }
  } catch (err) {
    console.warn('Could not load mountains:', err);
  }

  // Visual Shockwave for Flag Captures
  const shockGeo = new THREE.RingGeometry(0.3, 0.9, 48);
  shockGeo.rotateX(-Math.PI / 2);
  const shockMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color('#f59e0b'),
    transparent: true,
    opacity: 0,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  gameContext.shockwaveMesh = new THREE.Mesh(shockGeo, shockMat);
  gameContext.shockwaveMesh.position.set(0, 0.15, 0);
  gameContext.scene.add(gameContext.shockwaveMesh);

  // Setup Fireworks / Sparks Particle System
  setupParticleSystem();

  // Setup Proximity Tether Line & Ball Light
  setupProximityVisuals();
}

