function updateProximityVisuals(delta: number) {
  if (!gameContext.golfBall || !gameContext.scene) return;

  const ballPos = gameContext.golfBall.object?.position;
  const isBallLive = (gameContext.golfBall.isShotActive || gameContext.isTurnTransitioning) && ballPos && !isNaN(ballPos.x);

  if (gameContext.ballPointLight) {
    if (isBallLive && ballPos) {
      const activeTeam = gameContext.teams[gameContext.currentTeamTurnIdx];
      gameContext.ballPointLight.color.set(TEAMS_CONFIG[activeTeam.id].colorHex);
      gameContext.ballPointLight.position.copy(ballPos);
      gameContext.ballPointLight.intensity = gameContext.golfBall.isShotActive ? 3.0 : 1.2;
    } else {
      gameContext.ballPointLight.intensity = 0;
    }
  }

  let nearestFlag: FlagStickState | null = null;
  let minDistanceMeters = Infinity;

  if (isBallLive && ballPos) {
    gameContext.flagSticks.forEach(flag => {
      const dist = Math.hypot(ballPos.x - flag.targetPos.x, ballPos.z - flag.targetPos.z);
      if (dist < minDistanceMeters) {
        minDistanceMeters = dist;
        nearestFlag = flag;
      }
    });
  }

  const activeTeam = gameContext.teams[gameContext.currentTeamTurnIdx];
  const teamColor = TEAMS_CONFIG[activeTeam.id].colorHex;

  gameContext.flagSticks.forEach((flag, idx) => {
    const isTarget = idx === gameContext.selectedTargetFlagIdx;
    const isApproaching = flag === nearestFlag && minDistanceMeters < 35.0;

    const speed = isApproaching ? 0.65 : 0.35;
    flag.pulseWaveAnim = (flag.pulseWaveAnim + delta * speed) % 1.0;
    const p = flag.pulseWaveAnim;

    const pulseMat = flag.pulseWaveMesh.material as THREE.MeshBasicMaterial;
    if (isApproaching) {
      pulseMat.color.set(teamColor);
      const easeP = 1.0 - Math.pow(1.0 - p, 2);
      const s = 0.25 + easeP * 1.65;
      flag.pulseWaveMesh.scale.set(s, 1, s);
      pulseMat.opacity = Math.sin((1.0 - p) * Math.PI * 0.5) * 0.55;
    } else if (isTarget) {
      pulseMat.color.set('#facc15');
      const easeP = 1.0 - Math.pow(1.0 - p, 2);
      const s = 0.25 + easeP * 1.65;
      flag.pulseWaveMesh.scale.set(s, 1, s);
      pulseMat.opacity = (1.0 - p) * 0.22;
    } else {
      pulseMat.opacity = 0;
    }
  });

  if (isBallLive && ballPos && nearestFlag && minDistanceMeters < 28.0) {
    const targetPos = (nearestFlag as FlagStickState).targetPos;

    if (gameContext.proximityTetherLine) {
      const posAttr = gameContext.proximityTetherLine.geometry.attributes.position as THREE.BufferAttribute;
      posAttr.setXYZ(0, ballPos.x, Math.max(ballPos.y, targetPos.y + 0.03), ballPos.z);
      posAttr.setXYZ(1, targetPos.x, targetPos.y + 0.03, targetPos.z);
      posAttr.needsUpdate = true;
      (gameContext.proximityTetherLine.material as THREE.LineBasicMaterial).color.set(teamColor);
      gameContext.proximityTetherLine.visible = true;
    }
  } else {
    if (gameContext.proximityTetherLine) gameContext.proximityTetherLine.visible = false;
  }
}

function updateTacticalCallout() {
  const activeTeam = gameContext.teams[gameContext.currentTeamTurnIdx];
  if (!activeTeam || gameContext.flagSticks.length === 0) return;

  const shortTag: Record<TeamId, string> = {
    red: 'RED',
    blue: 'BLU',
    green: 'GRN',
    yellow: 'YEL',
  };

  // 1. DEFEND Line: Flag owned by activeTeam (or closest flag if none owned yet)
  let defendIdx = gameContext.flagSticks.findIndex((f) => f.capturedBy === activeTeam.id);
  if (defendIdx === -1) {
    defendIdx = 0;
  }
  gameContext.tacDefendFlagIdx = defendIdx;
  const defendFlag = gameContext.flagSticks[defendIdx];

  // 2. CAPTURE Line: Currently selected target flag (if not defendIdx) or an open/enemy flag
  let captureIdx = gameContext.selectedTargetFlagIdx;
  if (captureIdx === defendIdx) {
    const enemyOrOpenIdx = gameContext.flagSticks.findIndex(
      (f, idx) => idx !== defendIdx && f.capturedBy !== activeTeam.id
    );
    captureIdx = enemyOrOpenIdx !== -1 ? enemyOrOpenIdx : (defendIdx + 1) % gameContext.flagSticks.length;
  }
  gameContext.tacCaptureFlagIdx = captureIdx;
  const captureFlag = gameContext.flagSticks[captureIdx];

  const tacTextDefend = document.getElementById('tac-text-defend');
  const tacIconDefend = document.getElementById('tac-icon-defend');
  if (tacTextDefend && defendFlag) {
    const ownerStr = defendFlag.capturedBy ? shortTag[defendFlag.capturedBy] : activeTeam.id.toUpperCase();
    tacTextDefend.textContent = `DEFEND FLAG ${defendFlag.config.id} (${ownerStr}) - ${defendFlag.config.distanceYards} YD`;
  }
  if (tacIconDefend && defendFlag) {
    const c = defendFlag.capturedBy ? TEAMS_CONFIG[defendFlag.capturedBy].colorHex : activeTeam.colorHex;
    tacIconDefend.style.color = c;
  }

  const tacTextCapture = document.getElementById('tac-text-capture');
  const tacIconCapture = document.getElementById('tac-icon-capture');
  if (tacTextCapture && captureFlag) {
    const ownerStr = captureFlag.capturedBy ? shortTag[captureFlag.capturedBy] : 'OPEN';
    tacTextCapture.textContent = `CAPTURE FLAG ${captureFlag.config.id} (${ownerStr}) - ${captureFlag.config.distanceYards} YD`;
  }
  if (tacIconCapture && captureFlag) {
    const c = captureFlag.capturedBy ? TEAMS_CONFIG[captureFlag.capturedBy].colorHex : '#34d399';
    tacIconCapture.style.color = c;
  }
}

// --- HUD & UI UPDATE ---
function updateUI() {
  const activeTeam = gameContext.teams[gameContext.currentTeamTurnIdx];
  const targetFlag = gameContext.flagSticks[gameContext.selectedTargetFlagIdx];
  if (!targetFlag || !activeTeam) return;

  // 1. Top-Center Scorebug Center Block
  const badgeEl = document.getElementById('flag-badge');
  const ownerPill = document.getElementById('flag-owner-pill');
  const distEl = document.getElementById('target-dist-val');
  const terrainTagEl = document.getElementById('terrain-tag');
  const holderEl = document.getElementById('flag-best-holder');
  const radarTag = document.getElementById('radar-target-tag');
  const roundTitle = document.getElementById('round-title');

  if (badgeEl) badgeEl.textContent = `FLAG ${targetFlag.config.id}`;
  if (distEl) distEl.textContent = `${targetFlag.config.distanceYards}`;
  if (roundTitle) roundTitle.textContent = `ROUND ${gameContext.currentRound}/${TOTAL_ROUNDS}`;
  if (terrainTagEl) {
    terrainTagEl.textContent = `${targetFlag.config.terrainIcon} ${targetFlag.config.terrainLabel}`;
  }
  if (radarTag) {
    radarTag.textContent = `FLAG ${targetFlag.config.id} • ${targetFlag.config.distanceYards} YDS`;
  }

  if (ownerPill) {
    if (targetFlag.capturedBy) {
      const ownerTeam = TEAMS_CONFIG[targetFlag.capturedBy];
      ownerPill.className = `flag-owner-pill ${targetFlag.capturedBy}`;
      ownerPill.textContent = ownerTeam.name.toUpperCase();
    } else {
      ownerPill.className = 'flag-owner-pill neutral';
      ownerPill.textContent = 'OPEN';
    }
  }

  if (holderEl) {
    if (targetFlag.capturedBy && targetFlag.bestDistanceMeters < Infinity) {
      const ft = (targetFlag.bestDistanceMeters * 3.28084).toFixed(1);
      holderEl.textContent = `Record to beat: ${ft} ft (${TEAMS_CONFIG[targetFlag.capturedBy].name})`;
    } else {
      holderEl.textContent = 'Record: Open for capture!';
    }
  }

  updateAimAngleDisplay();

  // 5. Bottom-Center Active Player / Streak Banner
  const activeBanner = document.getElementById('active-player-banner');
  const turnBanner = document.getElementById('turn-banner');
  const turnPlayer = document.getElementById('turn-player-name');
  const shotCounter = document.getElementById('ap-shot-counter');
  const streakRibbonText = document.getElementById('streak-ribbon-text');

  if (activeBanner) {
    activeBanner.className = `hud-glass ${activeTeam.id}`;
  }
  if (turnBanner) {
    turnBanner.className = `ap-main-row ${activeTeam.id}`;
  }
  if (turnPlayer) {
    turnPlayer.textContent = activeTeam.name.toUpperCase();
  }
  if (shotCounter) {
    shotCounter.textContent = `SHOT ${gameContext.currentShotInTurn + 1}/${SHOTS_PER_TURN}`;
  }
  if (streakRibbonText) {
    const streak = gameContext.teamStreaks[activeTeam.id] || 0;
    if (streak >= 2) {
      streakRibbonText.textContent = `🔥 ON FIRE x${streak}`;
    } else if (streak === 1) {
      streakRibbonText.textContent = `🔥 HEATING UP • SHOT ${gameContext.currentShotInTurn + 1} OF ${SHOTS_PER_TURN}`;
    } else {
      streakRibbonText.textContent = `🔥 ACTIVE TURN • SHOT ${gameContext.currentShotInTurn + 1} OF ${SHOTS_PER_TURN}`;
    }
  }

  // Shot Pips
  for (let i = 0; i < 3; i++) {
    const pip = document.getElementById(`pip-${i}`);
    if (pip) {
      if (i < gameContext.currentShotInTurn) {
        pip.className = 'shot-pip used';
      } else if (i === gameContext.currentShotInTurn) {
        pip.className = 'shot-pip active';
      } else {
        pip.className = 'shot-pip';
      }
    }
  }

  // Update Scorebug Cards
  ALL_TEAM_IDS.forEach((id) => {
    const activeIdx = gameContext.teams.findIndex((t) => t.id === id);
    const isSlotActive = activeIdx !== -1;
    const isCurrentTurn = isSlotActive && activeIdx === gameContext.currentTeamTurnIdx;
    const teamState = isSlotActive ? gameContext.teams[activeIdx] : null;
    const scoreEl = document.getElementById(`score-${id}`);
    const cardEl = document.getElementById(`card-${id}`);
    const statusEl = document.getElementById(`status-${id}`);

    if (scoreEl) scoreEl.textContent = `${teamState ? teamState.flagsHeld : 0}`;
    if (cardEl) {
      cardEl.className = `sb-team-card team-card ${id} ${isCurrentTurn ? 'active' : ''} ${!isSlotActive ? 'inactive-slot' : ''}`;
    }
    if (statusEl) {
      statusEl.textContent = isCurrentTurn ? 'Active Turn' : 'Waiting';
    }
  });

  // Territory Dominance Mini Bar & Stats
  const totalFlags = FLAGS_CONFIG.length;
  let claimedTotal = 0;
  ALL_TEAM_IDS.forEach(id => {
    const team = gameContext.teams.find(t => t.id === id);
    const count = team ? team.flagsHeld : 0;
    claimedTotal += count;
    const seg = document.getElementById(`dom-${id}`);
    if (seg) {
      seg.style.width = `${(count / totalFlags) * 100}%`;
    }
  });
  const neutralSeg = document.getElementById('dom-neutral');
  if (neutralSeg) {
    const neutralCount = Math.max(0, totalFlags - claimedTotal);
    neutralSeg.style.width = `${(neutralCount / totalFlags) * 100}%`;
  }

  const domStats = document.getElementById('dom-stats-text');
  if (domStats) {
    const openCount = Math.max(0, totalFlags - claimedTotal);
    domStats.textContent = openCount > 0 ? `${openCount} FLAGS OPEN` : 'ALL FLAGS CLAIMED!';
  }

  updateTacticalCallout();
}

function showShotBanner(teamId: TeamId, shotNum: number, text: string) {
  const banner = document.getElementById('shot-banner');
  const badge = document.getElementById('shot-banner-badge');
  const dist = document.getElementById('shot-banner-dist');
  if (banner && badge && dist) {
    badge.className = `shot-banner-badge ${teamId}`;
    badge.textContent = `${TEAMS_CONFIG[teamId].name.toUpperCase()} SHOT ${shotNum}`;
    dist.textContent = text;
    banner.classList.add('show');
  }
}

function hideShotBanner() {
  document.getElementById('shot-banner')?.classList.remove('show');
}

function updateTelemetryHUD(
  speedMph: number,
  vlaDeg: number,
  hlaDeg: number,
  spinRpm: number,
  apexYards: number,
  carryYards: number,
  distYds: number,
  deviationYds: number
) {
  const speedEl = document.getElementById('telem-speed');
  const vlaEl = document.getElementById('telem-vla');
  const hlaEl = document.getElementById('telem-hla');
  const spinEl = document.getElementById('telem-spin');
  const apexEl = document.getElementById('telem-apex');
  const carryEl = document.getElementById('telem-carry');
  const devEl = document.getElementById('telem-deviation');
  const distEl = document.getElementById('telem-dist');

  if (speedEl) speedEl.textContent = `${Math.round(speedMph)}`;
  if (vlaEl) vlaEl.textContent = `${vlaDeg.toFixed(1)}°`;
  if (hlaEl) {
    hlaEl.textContent = Math.abs(hlaDeg) < 0.1 ? '0.0°' : `${Math.abs(hlaDeg).toFixed(1)}° ${hlaDeg > 0 ? 'R' : 'L'}`;
  }
  if (spinEl) spinEl.textContent = `${Math.round(spinRpm)}`;
  if (apexEl) apexEl.textContent = `${Math.round(apexYards * 3)}ft`;
  if (carryEl) carryEl.textContent = `${Math.round(carryYards)}`;
  if (distEl) distEl.textContent = `${distYds.toFixed(1)} YDS`;

  if (devEl) {
    if (Math.abs(deviationYds) < 0.2) {
      devEl.textContent = '0.0';
    } else if (deviationYds > 0) {
      devEl.textContent = `${deviationYds.toFixed(1)} R`;
    } else {
      devEl.textContent = `${Math.abs(deviationYds).toFixed(1)} L`;
    }
  }
}

// ==========================================
// --- TOP-RIGHT CIRCULAR COURSE RADAR ---
// ==========================================
function radarMapX(worldX: number): number {
  return 110 - (worldX / 54) * 78;
}

function radarMapY(worldZ: number): number {
  return 196 - (worldZ / 235) * 164;
}

function renderRadarMinimap() {
  const canvas = document.getElementById('radar-canvas') as HTMLCanvasElement;
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  const width = canvas.width;
  const height = canvas.height;
  const cx = width / 2;
  const cy = height / 2;
  const radius = Math.min(cx, cy) - 1;

  ctx.clearRect(0, 0, width, height);

  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, radius, 0, Math.PI * 2);
  ctx.clip();

  // 1. Deep Forest Perimeter Background
  const bgGrad = ctx.createRadialGradient(cx, cy, radius * 0.25, cx, cy, radius);
  bgGrad.addColorStop(0.0, '#1d4d26');
  bgGrad.addColorStop(0.75, '#13361a');
  bgGrad.addColorStop(1.0, '#0a1f0e');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Organic Winding Fairway Silhouette with Mowing Stripes
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(radarMapX(18), radarMapY(-4));
  ctx.bezierCurveTo(
    radarMapX(32), radarMapY(55),
    radarMapX(26), radarMapY(140),
    radarMapX(30), radarMapY(226)
  );
  ctx.bezierCurveTo(
    radarMapX(14), radarMapY(242),
    radarMapX(-14), radarMapY(242),
    radarMapX(-30), radarMapY(226)
  );
  ctx.bezierCurveTo(
    radarMapX(-26), radarMapY(140),
    radarMapX(-32), radarMapY(55),
    radarMapX(-18), radarMapY(-4)
  );
  ctx.closePath();

  const fwGrad = ctx.createLinearGradient(0, height, 0, 0);
  fwGrad.addColorStop(0.0, '#3b873e');
  fwGrad.addColorStop(0.5, '#4da349');
  fwGrad.addColorStop(1.0, '#3f9142');
  ctx.fillStyle = fwGrad;
  ctx.fill();

  // Clip mowing stripes inside fairway
  ctx.clip();
  ctx.lineWidth = 7;
  for (let y = -20; y < height + 20; y += 14) {
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.07)';
    ctx.beginPath();
    ctx.moveTo(cx - 80, y);
    ctx.lineTo(cx + 80, y - 18);
    ctx.stroke();
  }
  ctx.restore();

  // Fairway collar outline
  ctx.strokeStyle = 'rgba(134, 239, 172, 0.32)';
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // 3. Forest Tree Canopy Clusters along Left & Right Edges of Radar
  for (let i = 0; i < 28; i++) {
    const ang = (i / 28) * Math.PI * 2;
    const dist = radius - 6 - (i % 3) * 5;
    const tx = cx + Math.cos(ang) * dist;
    const ty = cy + Math.sin(ang) * dist;
    ctx.beginPath();
    ctx.arc(tx, ty, 11 + (i % 4) * 2.5, 0, Math.PI * 2);
    ctx.fillStyle = i % 2 === 0 ? 'rgba(18, 53, 24, 0.85)' : 'rgba(29, 74, 34, 0.78)';
    ctx.fill();
  }

  // 4. White Sculpted Sand Bunkers around Greens
  ctx.fillStyle = '#f5ebd6';
  ctx.strokeStyle = 'rgba(120, 95, 55, 0.55)';
  ctx.lineWidth = 0.8;
  BUNKER_DEFS.forEach((b) => {
    const cfg = FLAGS_CONFIG[b.flagIdx];
    if (!cfg) return;
    const fz = getFlagWorldZ(cfg);
    const bx = radarMapX(cfg.lateralOffsetMeters + b.offsetX);
    const by = radarMapY(fz + b.offsetZ);
    ctx.save();
    ctx.translate(bx, by);
    ctx.rotate(b.rotY);
    ctx.beginPath();
    ctx.ellipse(0, 0, 5.2, 3.0, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.restore();
  });

  // 5. Dotted Aim Line from Tee to AimPoint
  const teeX = radarMapX(0);
  const teeY = radarMapY(0);
  const ax = radarMapX(gameContext.aimPoint.x);
  const ay = radarMapY(gameContext.aimPoint.z);

  ctx.beginPath();
  ctx.moveTo(teeX, teeY);
  ctx.lineTo(ax, ay);
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.65)';
  ctx.lineWidth = 1.5;
  ctx.setLineDash([3, 3]);
  ctx.stroke();
  ctx.setLineDash([]);

  // 6. Active Flight Ball Trail on Radar
  if (gameContext.golfBall?.isShotActive) {
    const ballPos = gameContext.golfBall.object?.position;
    if (ballPos && !isNaN(ballPos.x) && !isNaN(ballPos.z)) {
      gameContext.ballTrailPoints.push({ x: ballPos.x, z: ballPos.z });
      if (gameContext.ballTrailPoints.length > 50) gameContext.ballTrailPoints.shift();

      if (gameContext.ballTrailPoints.length > 1) {
        ctx.beginPath();
        ctx.moveTo(radarMapX(gameContext.ballTrailPoints[0].x), radarMapY(gameContext.ballTrailPoints[0].z));
        for (let i = 1; i < gameContext.ballTrailPoints.length; i++) {
          ctx.lineTo(radarMapX(gameContext.ballTrailPoints[i].x), radarMapY(gameContext.ballTrailPoints[i].z));
        }
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.stroke();
      }

      const curX = radarMapX(ballPos.x);
      const curY = radarMapY(ballPos.z);
      ctx.beginPath();
      ctx.arc(curX, curY, 4.2, 0, Math.PI * 2);
      ctx.fillStyle = '#facc15';
      ctx.fill();
    }
  }

  // 7. Draw All 10 Greens & Colored Flag Pin Icons (matching ref.jpg)
  gameContext.flagSticks.forEach((flag, idx) => {
    const fx = radarMapX(flag.targetPos.x);
    const fy = radarMapY(flag.targetPos.z);
    const isTarget = idx === gameContext.selectedTargetFlagIdx;

    // Green turf pad
    ctx.beginPath();
    ctx.arc(fx, fy, isTarget ? 8.5 : 6.8, 0, Math.PI * 2);
    ctx.fillStyle = '#5ec259';
    ctx.fill();
    if (isTarget) {
      ctx.lineWidth = 1.8;
      ctx.strokeStyle = '#facc15';
      ctx.stroke();
    }

    let flagColor = '#f8fafc';
    if (flag.capturedBy && TEAMS_CONFIG[flag.capturedBy]) {
      flagColor = TEAMS_CONFIG[flag.capturedBy].colorHex;
    } else if (isTarget) {
      flagColor = '#38bdf8';
    }

    // Flagpole & Pennant Flag Icon
    ctx.beginPath();
    ctx.moveTo(fx - 1, fy + 3);
    ctx.lineTo(fx - 1, fy - 8);
    ctx.strokeStyle = '#0f172a';
    ctx.lineWidth = 1.6;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(fx - 1, fy - 8);
    ctx.lineTo(fx + 7, fy - 5);
    ctx.lineTo(fx - 1, fy - 2);
    ctx.closePath();
    ctx.fillStyle = flagColor;
    ctx.fill();
    ctx.strokeStyle = '#0f172a';
    ctx.lineWidth = 0.8;
    ctx.stroke();
  });

  // 8. Tee Box Marker at Bottom
  ctx.beginPath();
  ctx.arc(teeX, teeY, 4.5, 0, Math.PI * 2);
  ctx.fillStyle = '#facc15';
  ctx.fill();
  ctx.lineWidth = 1.5;
  ctx.strokeStyle = '#0f172a';
  ctx.stroke();

  ctx.restore();
}

// Click on circular radar to target flag directly (accounting for CSS scaling)
function setupRadarClickAim() {
  const canvas = document.getElementById('radar-canvas') as HTMLCanvasElement;
  if (!canvas) return;

  canvas.addEventListener('click', e => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / Math.max(1, rect.width);
    const scaleY = canvas.height / Math.max(1, rect.height);
    const clickX = (e.clientX - rect.left) * scaleX;
    const clickY = (e.clientY - rect.top) * scaleY;

    let closestIdx = -1;
    let closestDistSq = 20 * 20;

    gameContext.flagSticks.forEach((flag, idx) => {
      const fx = radarMapX(flag.targetPos.x);
      const fy = radarMapY(flag.targetPos.z);
      const distSq = (clickX - fx) * (clickX - fx) + (clickY - fy) * (clickY - fy);
      if (distSq < closestDistSq) {
        closestDistSq = distSq;
        closestIdx = idx;
      }
    });

    if (closestIdx >= 0) {
      playSoundClick();
      selectTargetFlag(closestIdx);
    }
  });
}

// ==========================================
// --- DYNAMIC DISTANCE PHYSICS CALIBRATOR ---
// ==========================================
const CALIBRATED_TABLE: Record<number, { speed: number; vla: number; spin: number }> = {
  55:  { speed: 56.2,  vla: 35.0, spin: 7000 },
  75:  { speed: 67.5,  vla: 32.0, spin: 6700 },
  95:  { speed: 78.4,  vla: 29.0, spin: 6400 },
  115: { speed: 88.9,  vla: 26.0, spin: 6000 },
  135: { speed: 99.0,  vla: 22.8, spin: 5500 },
  155: { speed: 108.6, vla: 20.0, spin: 4900 },
  175: { speed: 117.8, vla: 17.8, spin: 4400 },
  195: { speed: 126.9, vla: 16.0, spin: 3950 },
  215: { speed: 135.3, vla: 14.5, spin: 3500 },
  235: { speed: 144.0, vla: 13.2, spin: 3100 },
};

function getCalibratedShotForDistance(targetYards: number, powerPercent = 100, sprayDegrees = 0, spinAxisDegrees = 0) {
  const sorted = [55, 75, 95, 115, 135, 155, 175, 195, 215, 235];
  let baseSpeed = 54.0;
  let baseVla = 35.0;
  let baseSpin = 7000;

  if (targetYards <= sorted[0]) {
    const e = CALIBRATED_TABLE[55];
    baseSpeed = e.speed * (targetYards / 55);
    baseVla = e.vla;
    baseSpin = e.spin;
  } else if (targetYards >= sorted[sorted.length - 1]) {
    const e = CALIBRATED_TABLE[235];
    baseSpeed = e.speed * (targetYards / 235);
    baseVla = e.vla;
    baseSpin = e.spin;
  } else {
    for (let i = 0; i < sorted.length - 1; i++) {
      const d0 = sorted[i];
      const d1 = sorted[i + 1];
      if (targetYards >= d0 && targetYards <= d1) {
        const t = (targetYards - d0) / (d1 - d0);
        const e0 = CALIBRATED_TABLE[d0];
        const e1 = CALIBRATED_TABLE[d1];
        baseSpeed = e0.speed + t * (e1.speed - e0.speed);
        baseVla = e0.vla + t * (e1.vla - e0.vla);
        baseSpin = e0.spin + t * (e1.spin - e0.spin);
        break;
      }
    }
  }

  const actualSpeed = baseSpeed * (powerPercent / 100);

  return {
    ballSpeed: Math.round(actualSpeed * 10) / 10,
    verticalLaunchAngle: Math.round(baseVla * 10) / 10,
    horizontalLaunchAngle: Math.round(sprayDegrees * 10) / 10,
    spinSpeed: Math.round(baseSpin),
    spinAxis: Math.round(spinAxisDegrees),
    totalSpin: Math.round(baseSpin),
    backSpin: Math.round(baseSpin * 0.95),
    sideSpin: Math.round(baseSpin * Math.sin((spinAxisDegrees * Math.PI) / 180)),
  };
}

function fireSimulatedTestShot(mode: 'random' | 'pin' | 'short' | 'long' | 'hook' | 'slice' = 'random') {
  if (gameContext.isTurnTransitioning || gameContext.golfBall?.isShotActive) return;

  const targetDistYards = Math.hypot(
    gameContext.aimPoint.x - gameContext.startPoint.x,
    gameContext.aimPoint.z - gameContext.startPoint.z
  ) * 1.09361;

  let power = 100;
  let spray = 0;
  let spinAxis = 0;

  if (mode === 'pin') {
    // Dead center dart down the current aim line
    power = 100 + (Math.random() - 0.5) * 0.8;
    spray = (Math.random() - 0.5) * 0.25;
    spinAxis = 0;
  } else if (mode === 'short') {
    power = 86 + Math.random() * 4;
    spray = (Math.random() - 0.5) * 2;
    spinAxis = 0;
  } else if (mode === 'long') {
    power = 114 + Math.random() * 4;
    spray = (Math.random() - 0.5) * 2;
    spinAxis = 0;
  } else if (mode === 'hook') {
    power = 98 + Math.random() * 4;
    spray = -4.0 - Math.random() * 2;
    spinAxis = -12;
  } else if (mode === 'slice') {
    power = 98 + Math.random() * 4;
    spray = 4.0 + Math.random() * 2;
    spinAxis = 12;
  } else {
    // Spacebar: realistic dispersion relative to active aim line
    power = 96 + Math.random() * 8;
    spray = (Math.random() - 0.5) * 2.8;
    spinAxis = (Math.random() - 0.5) * 6;
  }

  const shot = getCalibratedShotForDistance(targetDistYards, power, spray, spinAxis);
  console.log(`[CTF Shot] Target Distance: ${Math.round(targetDistYards)}y, Mode: ${mode}, Speed: ${shot.ballSpeed} mph, VLA: ${shot.verticalLaunchAngle}°, HLA: ${shot.horizontalLaunchAngle}°`);
  launchShot(shot);
}

// --- SHOT LAUNCHING & PROCESSING ---
function launchShot(shot: OpenGolfSim.Shot) {
  if (gameContext.isTurnTransitioning) return;
  if (!shot.ballSpeed || gameContext.golfBall?.isShotActive) return;

  // Turn off flyover if active
  if (gameContext.isFlyoverActive) {
    toggleFlyoverCam();
  }

  // Clone shot so we never mutate caller's object, and preserve 100% 1:1 Launch Monitor telemetry (NO fake wind mutation!)
  const cleanShot: OpenGolfSim.Shot = {
    ...shot,
    ballSpeed: Math.max(1, Number(shot.ballSpeed) || 50),
    verticalLaunchAngle: Number(shot.verticalLaunchAngle) || 15,
    horizontalLaunchAngle: Number(shot.horizontalLaunchAngle) || 0,
    spinSpeed: (() => {
      const s = Number(shot.spinSpeed ?? (shot as any).totalSpin);
      return !isNaN(s) && s >= 0 ? s : 3500;
    })(),
    spinAxis: Number(shot.spinAxis) || 0,
  };

  // Sound: Club Impact
  playSoundClubImpact(cleanShot.ballSpeed);

  // Clear flight trail points & ensure 3D trail line is visible during flight
  gameContext.ballTrailPoints = [];
  if (gameContext.golfBall?.trail?.line) {
    gameContext.golfBall.trail.line.visible = true;
  }

  // Ensure golf ball is synchronized to current aim point before launch
  gameContext.golfBall?.aimAt(gameContext.aimPoint);

  const activeTeam = gameContext.teams[gameContext.currentTeamTurnIdx];
  gameContext.golfBall?.launchShot(cleanShot, activeTeam.coursePlayer?.player);

  // Show initial launch telemetry immediately
  updateTelemetryHUD(
    cleanShot.ballSpeed,
    cleanShot.verticalLaunchAngle,
    cleanShot.horizontalLaunchAngle,
    cleanShot.spinSpeed,
    0,
    0,
    0,
    0
  );

  const delayScale = Math.min(cleanShot.ballSpeed / 140, 1);
  gameContext.camera?.setTracking(true, delayScale);
}

// Check landing proximity across ALL 10 flags
function onShotEnded() {
  if (!gameContext.golfBall) return;

  // Immediately hide in-flight 3D ball trail & aim guide so post-shot Hero Cam is 100% clean
  if (gameContext.golfBall.trail?.line) {
    gameContext.golfBall.trail.line.visible = false;
  }
  if (gameContext.aimLaserLine) gameContext.aimLaserLine.visible = false;
  if (gameContext.aimReticleMesh) gameContext.aimReticleMesh.visible = false;

  // Sound: Landing Thud
  playSoundBallLand();

  const ballEndPos = gameContext.golfBall.stats?.endPosition || gameContext.golfBall.object?.position || new THREE.Vector3();
  const activeTeam = gameContext.teams[gameContext.currentTeamTurnIdx];
  const isInWater = Boolean((gameContext.golfBall as any).isInWater);
  const isInBunker = Boolean((gameContext.golfBall as any).isInBunker);
  const isInHole = Boolean((gameContext.golfBall as any).isInHole);

  // Total yards & offline deviation for telemetry card
  // Positive = Right of aim line, Negative = Left of aim line (matching GolfBall.getLateralDistance)
  const totalYards = Math.hypot(
    ballEndPos.x - gameContext.startPoint.x,
    ballEndPos.z - gameContext.startPoint.z
  ) * 1.09361;
  const aimDir = new THREE.Vector3().subVectors(gameContext.aimPoint, gameContext.startPoint);
  aimDir.y = 0;
  aimDir.normalize();
  const toBall = new THREE.Vector3().subVectors(ballEndPos, gameContext.startPoint);
  const lateralDeviationMeters = aimDir.x * toBall.z - aimDir.z * toBall.x;
  const lateralDeviationYards = lateralDeviationMeters * 1.09361;

  const apexYards = (gameContext.golfBall.stats?.apex || 0) * 1.09361;
  const carryYards = (gameContext.golfBall.stats?.carry || 0) * 1.09361;

  const lastShot = gameContext.golfBall.lastShot;
  if (lastShot) {
    updateTelemetryHUD(
      lastShot.ballSpeed,
      lastShot.verticalLaunchAngle,
      lastShot.horizontalLaunchAngle,
      lastShot.spinSpeed,
      apexYards,
      carryYards,
      totalYards,
      lateralDeviationYards
    );
  }

  // Find nearest flag on the map
  let nearestFlag: FlagStickState | null = null;
  let minDistanceMeters = Infinity;

  gameContext.flagSticks.forEach(flag => {
    const dist = Math.hypot(ballEndPos.x - flag.targetPos.x, ballEndPos.z - flag.targetPos.z);
    if (dist < minDistanceMeters) {
      minDistanceMeters = dist;
      nearestFlag = flag;
    }
  });

  if (isInHole && nearestFlag) {
    minDistanceMeters = 0;
  }

  const distFeet = minDistanceMeters * 3.28084;
  if (!isInWater) {
    placeBallMarker(ballEndPos, activeTeam.id, distFeet);
  }

  // Record MVP closest dart (only if dry)
  if (!isInWater && distFeet < gameContext.closestDartFt) {
    gameContext.closestDartFt = distFeet;
    gameContext.closestDartTeam = activeTeam.name;
  }

  let bannerText = `${distFeet.toFixed(1)} FT TO FLAG ${nearestFlag?.config.id}`;
  const maxCaptureRadiusMeters = 24.0; // ~78 feet capture threshold

  if (isInWater) {
    playSoundCrowdGasp();
    bannerText = `💧 WATER HAZARD! SPLASHED NEAR FLAG ${nearestFlag?.config.id}`;
  } else if (nearestFlag && minDistanceMeters <= maxCaptureRadiusMeters) {
    const fState = nearestFlag as FlagStickState;
    if (minDistanceMeters < fState.bestDistanceMeters) {
      // Record beaten! Check if capture or steal
      const prevOwner = fState.capturedBy;
      fState.bestDistanceMeters = minDistanceMeters;
      fState.capturedBy = activeTeam.id;
      fState.bestPlayerName = activeTeam.name;

      // Refresh high-res 1024x1024 target green texture & 512x320 flag cloth texture
      const teamDef = TEAMS_CONFIG[activeTeam.id];
      const isSelected = fState === gameContext.flagSticks[gameContext.selectedTargetFlagIdx];
      refreshFlagVisualTextures(fState, isSelected);

      // Update 3D Record-to-Beat ring on the green surface
      if (minDistanceMeters > 0.25 && minDistanceMeters < fState.greenRadius) {
        (fState.recordRingMesh.material as THREE.MeshBasicMaterial).color.set(teamDef.colorHex);
        fState.recordRingMesh.geometry.dispose();
        const newRecordGeo = new THREE.RingGeometry(
          Math.max(0.18, minDistanceMeters - 0.08),
          minDistanceMeters + 0.08,
          96
        );
        newRecordGeo.rotateX(-Math.PI / 2);
        conformRingToTerrain(
          newRecordGeo,
          fState.targetPos.x,
          fState.targetPos.z,
          fState.targetPos.y - 0.12,
          0.018
        );
        fState.recordRingMesh.geometry = newRecordGeo;
        fState.recordRingMesh.visible = true;
      } else {
        fState.recordRingMesh.visible = false;
      }

      // 3D Shockwave & Fireworks particles
      triggerCaptureShockwave(fState.targetPos, teamDef.colorHex);

      // Increment active team streak & reset previous owner's streak if stolen
      gameContext.teamStreaks[activeTeam.id] = (gameContext.teamStreaks[activeTeam.id] || 0) + 1;
      if (prevOwner && prevOwner !== activeTeam.id) {
        gameContext.teamStreaks[prevOwner] = 0;
      }

      // Refresh 3D LaserBeams so newly captured flag immediately projects its team laser
      updateTargetHighlight();

      // Recalculate flag counts
      recalculateFlagCounts();

      // Track longest capture
      if (fState.config.distanceYards > gameContext.longestCaptureYds) {
        gameContext.longestCaptureYds = fState.config.distanceYards;
        gameContext.longestCaptureTeam = activeTeam.name;
      }

      const holeOutTag = isInHole ? 'HOLE-OUT! ' : '';
      if (prevOwner && prevOwner !== activeTeam.id) {
        gameContext.stealsCount[activeTeam.id]++;
        playSoundFlagStolen();
        bannerText = `🚩 ${holeOutTag}CAPTURED! ${distFeet.toFixed(1)} FT (STOLEN FROM ${TEAMS_CONFIG[prevOwner].name.toUpperCase()}!)`;
        showCaptureModal(`FLAG ${fState.config.id} STOLEN!`, `${activeTeam.name.toUpperCase()} STOLE FLAG!`, `${distFeet.toFixed(1)} ft beats ${TEAMS_CONFIG[prevOwner].name}`, activeTeam.id);
      } else {
        playSoundFlagCapture();
        bannerText = `🚩 ${holeOutTag}FLAG ${fState.config.id} CAPTURED! (${distFeet.toFixed(1)} FT)`;
        showCaptureModal(`FLAG ${fState.config.id} CLAIMED!`, `${activeTeam.name.toUpperCase()} CAPTURED!`, `Closest ball: ${distFeet.toFixed(1)} ft`, activeTeam.id);
      }
    } else {
      // Near miss sound
      if (distFeet < 6) {
        playSoundCrowdGasp();
      }
      const bunkerSuffix = isInBunker ? ' [SAND BUNKER]' : '';
      bannerText = `${distFeet.toFixed(1)} FT TO FLAG ${fState.config.id}${bunkerSuffix} (Record: ${(fState.bestDistanceMeters * 3.28084).toFixed(1)} ft)`;
    }
  } else {
    if (distFeet < 35) {
      playSoundCrowdGasp();
    }
    if (isInBunker) {
      bannerText = `🏖️ PLUGGED IN BUNKER! (${distFeet.toFixed(1)} FT TO FLAG ${nearestFlag?.config.id})`;
    }
  }

  // Proximity Bullseye Special Popup (< 6.5 ft = inside 2m circle)
  if (!isInWater && distFeet <= 6.5) {
    showBullseyeModal(distFeet);
  }

  showShotBanner(activeTeam.id, gameContext.currentShotInTurn + 1, bannerText);
  updateUI();
  renderFlagSelectorStrip();

  gameContext.isTurnTransitioning = true;

  // 2.2s elevated hero cam over resting ball before returning to tee
  setTimeout(() => {
    hideShotBanner();
    gameContext.isTurnTransitioning = false;

    // Advance turn logic
    gameContext.currentShotInTurn++;
    if (gameContext.currentShotInTurn >= SHOTS_PER_TURN) {
      gameContext.currentShotInTurn = 0;
      gameContext.currentTeamTurnIdx++;

      if (gameContext.currentTeamTurnIdx >= gameContext.teams.length) {
        gameContext.currentTeamTurnIdx = 0;
        gameContext.currentRound++;

        if (gameContext.currentRound > TOTAL_ROUNDS) {
          triggerGameOver();
          return;
        } else {
          updateWindCondition(true);
        }
      }
    }

    resetForNextTurn();
  }, 2200);
}

function recalculateFlagCounts() {
  gameContext.teams.forEach(t => t.flagsHeld = 0);
  gameContext.flagSticks.forEach(f => {
    if (f.capturedBy) {
      const team = gameContext.teams.find(t => t.id === f.capturedBy);
      if (team) team.flagsHeld++;
    }
  });
}

function showCaptureModal(badge: string, title: string, details: string, teamId: TeamId) {
  const modal = document.getElementById('capture-modal');
  const badgeEl = document.getElementById('modal-badge');
  const titleEl = document.getElementById('modal-winner');
  const detailsEl = document.getElementById('modal-details');

  if (modal && badgeEl && titleEl && detailsEl) {
    badgeEl.textContent = badge;
    titleEl.className = `modal-winner ${teamId}`;
    titleEl.textContent = title;
    detailsEl.textContent = details;
    modal.classList.add('show');

    setTimeout(() => {
      modal.classList.remove('show');
    }, 2800);
  }
}

function resetForNextTurn() {
  const targetFlag = gameContext.flagSticks[gameContext.selectedTargetFlagIdx];
  gameContext.camera?.setTracking(false);
  gameContext.camera?.setPositions(gameContext.startPoint, gameContext.aimPoint);
  gameContext.golfBall?.reset(gameContext.aimPoint, gameContext.startPoint, targetFlag?.targetPos);
  gameContext.golfBall?.aimAt(gameContext.aimPoint);
  updateUI();
}

function handleMulligan() {
  if (gameContext.golfBall?.isShotActive || gameContext.isTurnTransitioning) return;

  // Remove the last ball marker if present
  if (gameContext.ballMarkers.length > 0) {
    const lastMarker = gameContext.ballMarkers.pop();
    if (lastMarker && gameContext.scene) {
      gameContext.scene.remove(lastMarker);
    }
  }

  // Decrement shot count
  if (gameContext.currentShotInTurn > 0) {
    gameContext.currentShotInTurn--;
  }

  resetForNextTurn();
  showShotBanner(gameContext.teams[gameContext.currentTeamTurnIdx].id, gameContext.currentShotInTurn + 1, 'MULLIGAN - REHIT SHOT!');
  playSoundClick();
}

function triggerGameOver() {
  gameContext.isTurnTransitioning = true;

  const gameOverModal = document.getElementById('game-over');
  const winnerTitle = document.getElementById('game-over-winner');
  const finalContainer = document.getElementById('final-scores-container');

  // Find team with most flags
  let bestScore = -1;
  let winners: TeamState[] = [];
  gameContext.teams.forEach(t => {
    if (t.flagsHeld > bestScore) {
      bestScore = t.flagsHeld;
      winners = [t];
    } else if (t.flagsHeld === bestScore) {
      winners.push(t);
    }
  });

  if (winnerTitle) {
    if (winners.length === 1 && bestScore > 0) {
      winnerTitle.className = `game-over-title ${winners[0].id}`;
      winnerTitle.textContent = `${winners[0].name.toUpperCase()} WINS!`;
      playSoundFlagCapture();
    } else {
      winnerTitle.className = 'game-over-title tie';
      winnerTitle.textContent = 'MATCH DRAW!';
    }
  }

  if (finalContainer) {
    finalContainer.innerHTML = '';
    gameContext.teams.forEach(t => {
      const box = document.createElement('div');
      box.className = `score-box ${t.id}`;
      box.innerHTML = `
        <span class="score-num">${t.flagsHeld}</span>
        <span class="score-lbl">${t.name}</span>
      `;
      finalContainer.appendChild(box);
    });
  }

  // Populate MVP Stats
  const mvpClosest = document.getElementById('mvp-closest');
  const mvpSteals = document.getElementById('mvp-steals');
  const mvpLongest = document.getElementById('mvp-longest');

  if (mvpClosest) {
    mvpClosest.textContent = gameContext.closestDartFt < Infinity ? `${gameContext.closestDartFt.toFixed(1)} ft (${gameContext.closestDartTeam})` : '--';
  }
  if (mvpSteals) {
    let maxSteals = 0;
    let stealTeam = '--';
    ALL_TEAM_IDS.forEach(id => {
      if (gameContext.stealsCount[id] > maxSteals) {
        maxSteals = gameContext.stealsCount[id];
        stealTeam = `${TEAMS_CONFIG[id].name} (${maxSteals})`;
      }
    });
    mvpSteals.textContent = maxSteals > 0 ? stealTeam : 'None';
  }
  if (mvpLongest) {
    mvpLongest.textContent = gameContext.longestCaptureYds > 0 ? `${gameContext.longestCaptureYds}y (${gameContext.longestCaptureTeam})` : '--';
  }

  gameOverModal?.classList.add('show');
}

// ==========================================
// --- SETUP & INITIALIZATION ---
// ==========================================
async function setupGame() {
  await setupWorld();

  gameContext.scene = new THREE.Scene();
  gameContext.scene.background = skyColor;
  gameContext.fog = new THREE.Fog(fogColor, 350, 1500);
  gameContext.scene.fog = gameContext.fog;

  gameContext.lightGroup = new CourseLight({
    color: sunColor,
    ambient: { enabled: true, intensity: 0.65 },
    directional: { enabled: true, intensity: 2.35 },
  });
  if (gameContext.lightGroup.overhead) {
    const dirLight = gameContext.lightGroup.overhead;
    dirLight.color.set('#ffd285');
    dirLight.intensity = 2.35;
    // Low Golden Hour sun in front-left sky (+X is screen left, +Z is downrange) casting long shadows across tee & fairway
    dirLight.target.position.set(0, 0, 105);
    dirLight.position.set(185, 62, 195);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 20;
    dirLight.shadow.camera.far = 420;
    dirLight.shadow.camera.left = -145;
    dirLight.shadow.camera.right = 145;
    dirLight.shadow.camera.top = 95;
    dirLight.shadow.camera.bottom = -95;
    dirLight.shadow.bias = -0.00035;
    dirLight.shadow.normalBias = 0.02;
    dirLight.shadow.camera.updateProjectionMatrix();
    dirLight.target.updateMatrixWorld();
  }
  gameContext.scene.add(gameContext.lightGroup);

  // Warm Golden Hour sky-to-turf Hemisphere fill light
  const hemiLight = new THREE.HemisphereLight('#ffe5b4', '#2c4c24', 0.65);
  gameContext.scene.add(hemiLight);

  if (!gameContext.renderer) throw new Error('Renderer missing');
  gameContext.meshLoader = new MeshLoader(gameContext.renderer, gameContext.loadingScreen?.manager);

  await createDrivingRange();
  createFlagTargets();

  if (!gameContext.ground) throw new Error('Ground missing');
  gameContext.camera = new ShotPerspectiveCamera({
    scene: gameContext.ground,
    fov: 28,
    far: 1600,
    autoPosition: true,
    cameraOffsetX: 0,
  });

  // Procedural 3D TSL Volumetric Clouds & Horizon Sky Dome (placed at radius 1350m behind the 900m mountains)
  gameContext.clouds = new VolumetricClouds(gameContext.camera, {
    radius: 1350,
    density: 0.4,
    opacity: 0.85,
    scale: 9,
    skyColor,
    fogColor,
    cloudColor,
    position: new THREE.Vector3(0, 0, 0),
  });
  gameContext.scene.add(gameContext.clouds.object);

  gameContext.controls = new CourseKeyboardControls({ testShots: false, swipeShots: true });
  gameContext.controls.on('aim', aimKeys => {
    if (gameContext.camera) gameContext.camera.aimKeys = aimKeys;
  });
  gameContext.controls.on('toggleStats', () => gameContext.stats?.toggle());

  // Golf ball flight with sculpted 3D terrain + greens + bunkers + water colliders
  if (!gameContext.setupData) throw new Error('setupData missing');
  gameContext.setupData.practiceMode = true;
  gameContext.golfBall = new GolfBall(gameContext.scene, {
    setupData: gameContext.setupData,
    clearTrail: 'end',
    groundMeshes: [gameContext.ground, ...gameContext.greenMeshes],
  });
  gameContext.golfBall.on('shotEnded', onShotEnded);

  // Setup players from setupData if provided, while keeping Red Team / Blue Team / etc. (or saved custom names)
  const players = gameContext.setupData?.players || [];
  if (players.length >= 2) {
    const count = Math.min(players.length, 4);
    setTeamCount(count);
    players.slice(0, count).forEach((p, idx) => {
      if (gameContext.teams[idx]) {
        gameContext.teams[idx].coursePlayer = new CoursePlayer(p);
      }
    });
    renderScoreboardCards();
  } else {
    setTeamCount(2);
  }

  if (gameContext.setupData?.showLaunchStatus) {
    gameContext.launchMonitor = new UILaunchMonitor('#lm-status');
  }
  gameContext.stats = new UIStats('#render-stats', { hidden: true, renderer: gameContext.renderer?.renderer });

  gameContext.mainMenu = new UIMainMenu('#top-left');
  gameContext.mainMenu.on('stats', () => gameContext.stats?.toggle());
  gameContext.mainMenu.on('exit', () => app.exit());

  gameContext.renderer.generateEnvironment(gameContext.scene, gameContext.clouds.object);
  // Use 4x MSAA RenderPipeline pass without blurry Gaussian bloom so 3D target rings & signs stay razor-sharp
  const savedQuality = gameContext.renderer.qualityLevel;
  if (savedQuality > QualityMode.Low) {
    gameContext.renderer.qualityLevel = QualityMode.Medium;
  }
  gameContext.renderer.setupPostProcessing(gameContext.scene, gameContext.camera);
  gameContext.renderer.qualityLevel = savedQuality;
  await gameContext.renderer.compile(gameContext.scene, gameContext.camera);

  // AAA Dynamic Particle VFX System
  gameContext.particleSystem = new ArcadeParticleSystem(gameContext.scene, 1400);

  // Wire Collapsible Settings Drawer Gear Button
  document.getElementById('btn-toggle-setup')?.addEventListener('click', () => {
    const drawer = document.getElementById('setup-drawer');
    if (drawer) {
      drawer.classList.toggle('open');
      playSoundClick();
    }
  });

  // Wire Graphics Quality Buttons
  const qualityMap: Record<string, QualityMode> = {
    low: QualityMode.Low,
    medium: QualityMode.Medium,
    high: QualityMode.High,
    epic: QualityMode.Epic,
  };
  document.querySelectorAll('.q-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      const qKey = btn.getAttribute('data-quality');
      if (qKey && qualityMap[qKey] !== undefined) {
        setGraphicsQuality(qualityMap[qKey]);
        playSoundClick();
      }
    });
  });
  updateQualityUI(gameContext.currentQuality);

  // Wire Dialog & Navigation Buttons
  document.getElementById('btn-exit')?.addEventListener('click', () => app.exit());
  document.getElementById('btn-replay')?.addEventListener('click', () => window.location.reload());

  // Wire Target Flag Navigation Buttons
  document.getElementById('btn-prev-flag')?.addEventListener('click', () => {
    playSoundClick();
    selectTargetFlag(gameContext.selectedTargetFlagIdx - 1);
  });
  document.getElementById('btn-next-flag')?.addEventListener('click', () => {
    playSoundClick();
    selectTargetFlag(gameContext.selectedTargetFlagIdx + 1);
  });

  // Wire Aim Left / Right / Recenter Buttons
  // Note: around +Y axis in Three.js, +angle rotates toward +X (Screen LEFT), -angle rotates toward -X (Screen RIGHT)
  document.getElementById('btn-aim-left')?.addEventListener('click', () => nudgeAim(1.5));
  document.getElementById('btn-aim-right')?.addEventListener('click', () => nudgeAim(-1.5));
  document.getElementById('btn-nudge-left-2')?.addEventListener('click', () => nudgeAim(2.0));
  document.getElementById('btn-nudge-right-2')?.addEventListener('click', () => nudgeAim(-2.0));
  document.getElementById('btn-recenter-aim')?.addEventListener('click', () => recenterAim());

  // Wire Drone Green Cam Flyover Buttons
  document.getElementById('btn-drone-cam')?.addEventListener('click', () => toggleFlyoverCam());
  const canvasEl = document.getElementById('canvas');
  if (canvasEl) {
    const raycaster = new THREE.Raycaster();
    const mousePos = new THREE.Vector2();

    canvasEl.addEventListener('pointerdown', (e) => {
      if (gameContext.isFlyoverActive) {
        toggleFlyoverCam();
        return;
      }
      if (gameContext.golfBall?.isShotActive || !gameContext.camera) return;

      const rect = canvasEl.getBoundingClientRect();
      mousePos.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      mousePos.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(mousePos, gameContext.camera);

      const flagGroups = gameContext.flagSticks.map((f) => f.group);
      const hits = raycaster.intersectObjects(flagGroups, true);
      if (hits.length > 0) {
        let obj: THREE.Object3D | null = hits[0].object;
        while (obj && obj.parent && obj.userData?.flagIdx === undefined) {
          obj = obj.parent;
        }
        if (obj?.userData?.flagIdx !== undefined) {
          playSoundClick();
          selectTargetFlag(obj.userData.flagIdx);
        }
      }
    });
  }

  // Wire Mulligan Button
  document.getElementById('btn-mulligan')?.addEventListener('click', () => handleMulligan());

  // Wire Team Count Buttons
  document.getElementById('btn-teams-2')?.addEventListener('click', () => setTeamCount(2));
  document.getElementById('btn-teams-3')?.addEventListener('click', () => setTeamCount(3));
  document.getElementById('btn-teams-4')?.addEventListener('click', () => setTeamCount(4));

  // Wire Tactical Callout Buttons (Bottom-Right)
  document.getElementById('tac-line-defend')?.addEventListener('click', () => {
    playSoundClick();
    selectTargetFlag(gameContext.tacDefendFlagIdx);
  });
  document.getElementById('tac-line-capture')?.addEventListener('click', () => {
    playSoundClick();
    selectTargetFlag(gameContext.tacCaptureFlagIdx);
  });

  // Wire Audio Mute Toggle
  document.getElementById('btn-mute')?.addEventListener('click', () => {
    gameContext.audioMuted = !gameContext.audioMuted;
    const btn = document.getElementById('btn-mute');
    if (btn) btn.textContent = gameContext.audioMuted ? '🔇 Audio Muted' : '🔊 Audio On';
  });

  // Initialize Wind Condition & Minimap Radar click listener
  updateWindCondition(false);
  setupRadarClickAim();

  // Initialize Target Flag 0 (55y) and render UI
  selectTargetFlag(0);
}

function setGraphicsQuality(level: QualityMode) {
  gameContext.currentQuality = level;
  if (gameContext.renderer && gameContext.camera && gameContext.scene) {
    gameContext.renderer.setQualityLevel(level);
    if (level > QualityMode.Low) {
      gameContext.renderer.qualityLevel = QualityMode.Medium;
      gameContext.renderer.setupPostProcessing(gameContext.scene, gameContext.camera);
      gameContext.renderer.qualityLevel = level;
    } else {
      gameContext.renderer.pipeline = undefined;
    }
  }
  try {
    localStorage.setItem('ogs_graphics_quality', qualityToString(level));
  } catch (e) {}
  updateQualityUI(level);

  // Volumetric floodlight beams
  gameContext.volumetricBeams.forEach((beam) => {
    beam.visible = level > QualityMode.Low;
    if (beam.material instanceof THREE.ShaderMaterial) {
      const alpha = level >= QualityMode.VeryHigh ? 0.22 : level === QualityMode.High ? 0.16 : 0.08;
      beam.material.uniforms.intensity.value = alpha;
    }
  });

  // Soft shadows
  if (gameContext.lightGroup?.overhead) {
    gameContext.lightGroup.overhead.castShadow = level > QualityMode.Low;
  }
}

function updateQualityUI(level: QualityMode) {
  const str = qualityToString(level);
  document.querySelectorAll('.q-btn').forEach((b) => {
    const q = b.getAttribute('data-quality');
    if (q === str) {
      b.classList.add('active');
    } else {
      b.classList.remove('active');
    }
  });
}

function animate(animDelta: number) {
  requestAnimationFrame(animate);

  gameContext.stats?.begin();
  const delta = gameContext.timer.getDelta();

  if (gameContext.golfBall) {
    gameContext.golfBall.update(delta);
  }

  if (gameContext.controls) gameContext.controls.update(delta);
  if (gameContext.clouds) {
    if (gameContext.clouds.timeUniform) {
      gameContext.clouds.timeUniform.value += delta * 0.12;
    }
    gameContext.clouds.update(delta);
  }

  // Animate 3D vertical beacon (gentle spin + hide when camera is close to green)
  const camPos = gameContext.camera?.position;
  if (gameContext.targetBeaconGroup) {
    gameContext.targetBeaconGroup.rotation.y += delta * 0.4;
    const selFlag = gameContext.flagSticks[gameContext.selectedTargetFlagIdx];
    const beaconDist = camPos && selFlag ? camPos.distanceTo(selFlag.targetPos) : 100;
    gameContext.targetBeaconGroup.visible =
      !gameContext.isTurnTransitioning &&
      !gameContext.isFlyoverActive &&
      beaconDist > 42.0;
  }

  // Animate 3D capture shockwave
  if (gameContext.shockwaveMesh && gameContext.shockwaveAnimTime >= 0) {
    gameContext.shockwaveAnimTime += delta * 1.5;
    const progress = gameContext.shockwaveAnimTime;
    if (progress <= 1.0) {
      const s = 1.0 + progress * 14.0;
      gameContext.shockwaveMesh.scale.set(s, 1, s);
      (gameContext.shockwaveMesh.material as THREE.MeshBasicMaterial).opacity = (1 - progress) * 0.9;
    } else {
      gameContext.shockwaveAnimTime = -1;
      (gameContext.shockwaveMesh.material as THREE.MeshBasicMaterial).opacity = 0;
    }
  }

  // Animate 3D Waving Flag Cloth on All Flagpoles & Hide 3D Distance Signs When Camera is Close
  const waveTime = Date.now() * 0.005;
  gameContext.flagSticks.forEach(flag => {
    const geo = flag.flagMesh.geometry;
    const pos = geo.attributes.position;
    if (pos) {
      for (let i = 0; i < pos.count; i++) {
        const u = pos.getX(i);
        const amp = Math.max(0, (u + 0.43) / 0.86) * 0.06; // Pinned at pole (u = -0.43), ripples toward free edge
        pos.setZ(i, Math.sin(waveTime * 3 + u * 12) * amp);
      }
      pos.needsUpdate = true;
    }
    if (flag.signSprite) {
      flag.signSprite.visible = false;
    }
  });

  // Update Celebration Particles & Dynamic Proximity System
  updateParticles(delta);
  if (gameContext.particleSystem) {
    gameContext.particleSystem.update(delta);
  }
  updateProximityVisuals(delta);

  // Camera Management & Live Aim Sync
  if (gameContext.scene && gameContext.golfBall && gameContext.camera) {
    const ballPos = gameContext.golfBall.object?.position;
    if (gameContext.isFlyoverActive) {
      // Smoothly frame aerial inspection view of the target green
      const targetFlag = gameContext.flagSticks[gameContext.selectedTargetFlagIdx];
      if (targetFlag) {
        const tPos = targetFlag.targetPos;
        const targetCamPos = new THREE.Vector3(tPos.x + 9, tPos.y + 9.0, tPos.z - 16);
        gameContext.camera.position.lerp(targetCamPos, delta * 3.5);
        gameContext.camera.lookAt(tPos.x, tPos.y + 0.4, tPos.z);
      }
    } else if (
      gameContext.golfBall.isShotActive &&
      ballPos &&
      !isNaN(ballPos.x) &&
      !isNaN(ballPos.y) &&
      !isNaN(ballPos.z)
    ) {
      gameContext.camera.track(delta, gameContext.startPoint, ballPos);

      // Live real-time flight telemetry update
      const lastShot = gameContext.golfBall.lastShot;
      if (lastShot) {
        const curTotalYds = Math.hypot(
          ballPos.x - gameContext.startPoint.x,
          ballPos.z - gameContext.startPoint.z
        ) * 1.09361;
        const curCarryYds = (gameContext.golfBall.stats?.carry || 0) * 1.09361;
        const curApexYds = (gameContext.golfBall.stats?.apex || 0) * 1.09361;
        const curLatYds = (gameContext.golfBall.stats?.lateral || 0) * 1.09361;
        updateTelemetryHUD(
          lastShot.ballSpeed,
          lastShot.verticalLaunchAngle,
          lastShot.horizontalLaunchAngle,
          lastShot.spinSpeed,
          curApexYds,
          curCarryYds,
          curTotalYds,
          curLatYds
        );
      }
    } else if (gameContext.isTurnTransitioning && ballPos && !isNaN(ballPos.x)) {
      // POST-SHOT HERO CAM: elevated 3.5m above ground, 12m back from ball looking at the pin
      const targetFlag = gameContext.flagSticks[gameContext.selectedTargetFlagIdx];
      const targetPin = targetFlag ? targetFlag.targetPos : gameContext.aimPoint;
      const toPin = new THREE.Vector3().subVectors(targetPin, ballPos).normalize();
      toPin.y = 0;
      if (toPin.lengthSq() < 0.001) toPin.set(0, 0, 1);

      const desiredHeroPos = ballPos.clone().addScaledVector(toPin, -12);
      desiredHeroPos.y = Math.max(3.5, ballPos.y + 3.2);
      desiredHeroPos.x += 1.5;

      gameContext.camera.position.lerp(desiredHeroPos, delta * 3.5);
      gameContext.camera.lookAt(ballPos.x, Math.max(0.5, ballPos.y + 0.4), ballPos.z);
    } else {
      // FREE AIM MODE: Update camera aim and CONTINUOUSLY synchronize golf ball facing direction!
      gameContext.camera.update(delta, gameContext.startPoint, gameContext.aimPoint);

      if (!gameContext.golfBall.isShotActive) {
        // Essential: Keep golf ball physically oriented along the exact live aim line
        gameContext.golfBall.aimAt(gameContext.aimPoint);
        updateAimAngleDisplay();
      }
    }
  }

  if (gameContext.camera && gameContext.scene) {
    gameContext.renderer?.render(gameContext.scene, gameContext.camera);
  }

  // Render 2D Range Radar Minimap
  renderRadarMinimap();

  gameContext.stats?.end();
  gameContext.timer.update(animDelta);
}

let isGameInitialized = false;

function preLoad() {
  if (isGameInitialized) return;
  isGameInitialized = true;
  document.body.style.opacity = '1';
  gameContext.loadingScreen = new UILoadingScreen(document.body, { loadingPrefix: 'Preparing Capture The Flag' });
  gameContext.loadingScreen.on('load', () => {
    requestAnimationFrame(animate);
    app.setLoaded();
  });
  gameContext.loadingScreen.load(setupGame);
}

function initializeDebug() {
  if (isGameInitialized) return;
  gameContext.setupData = generateSetupData(2);
  preLoad();
}

function initializeSetup(payload: any) {
  if (isGameInitialized) return;
  gameContext.setupData = (payload?.setupData || generateSetupData(2)) as OpenGolfSim.SetupData;
  preLoad();
}

// AppBridge Handshake
app.initialize(() => {
  document.body.style.opacity = '1';
  if (app.appType === 'web') {
    initializeDebug();
  } else {
    setTimeout(() => {
      if (!isGameInitialized) {
        initializeDebug();
      }
    }, 600);
  }
});

app.on('setup', initializeSetup);
app.on('shot', shot => launchShot(shot));

// Test shot hotkeys, Aim nudge keys & Mulligan key
window.addEventListener('keydown', e => {
  if (e.repeat) return;
  // Ignore hotkeys while editing team/player names inline
  const activeTag = (document.activeElement as HTMLElement)?.tagName;
  if (activeTag === 'INPUT' || activeTag === 'TEXTAREA') return;

  switch (e.code) {
    case 'Space':
      e.preventDefault();
      fireSimulatedTestShot('random');
      break;
    case 'KeyP':
      e.preventDefault();
      fireSimulatedTestShot('pin');
      break;
    case 'Digit1':
      e.preventDefault();
      if (e.shiftKey) fireSimulatedTestShot('short');
      else selectTargetFlag(0);
      break;
    case 'Digit2':
      e.preventDefault();
      if (e.shiftKey) fireSimulatedTestShot('long');
      else selectTargetFlag(1);
      break;
    case 'Digit3':
      e.preventDefault();
      if (e.shiftKey) fireSimulatedTestShot('hook');
      else selectTargetFlag(2);
      break;
    case 'Digit4':
      e.preventDefault();
      if (e.shiftKey) fireSimulatedTestShot('slice');
      else selectTargetFlag(3);
      break;
    case 'Digit5':
      e.preventDefault();
      selectTargetFlag(4);
      break;
    case 'Digit6':
      e.preventDefault();
      selectTargetFlag(5);
      break;
    case 'Digit7':
      e.preventDefault();
      selectTargetFlag(6);
      break;
    case 'Digit8':
      e.preventDefault();
      selectTargetFlag(7);
      break;
    case 'Digit9':
      e.preventDefault();
      selectTargetFlag(8);
      break;
    case 'Digit0':
      e.preventDefault();
      selectTargetFlag(9);
      break;
    case 'KeyV':
      e.preventDefault();
      toggleFlyoverCam();
      break;
    case 'KeyZ':
      e.preventDefault();
      handleMulligan();
      break;
    case 'KeyC':
      e.preventDefault();
      recenterAim();
      break;
    case 'Tab':
    case 'BracketRight':
      e.preventDefault();
      playSoundClick();
      selectTargetFlag(gameContext.selectedTargetFlagIdx + 1);
      break;
    case 'BracketLeft':
      e.preventDefault();
      playSoundClick();
      selectTargetFlag(gameContext.selectedTargetFlagIdx - 1);
      break;
    case 'KeyA':
      e.preventDefault();
      nudgeAim(1.5);
      break;
    case 'KeyD':
      e.preventDefault();
      nudgeAim(-1.5);
      break;
    case 'KeyM':
      e.preventDefault();
      gameContext.audioMuted = !gameContext.audioMuted;
      const btn = document.getElementById('btn-mute');
      if (btn) btn.textContent = gameContext.audioMuted ? '🔇' : '🔊';
      break;
  }
});
